 std::string source="#version 450\nlayout(local_size_x=64)in;\n"+input.str()+fogSource.str()+"\nlayout(set=0,binding=1)buffer Output{vec4 result[];};layout(set=0,binding=2)readonly buffer Points{vec4 points[];};void main(){uint i=gl_GlobalInvocationID.x;if(i>=1024)return;vec2 p=points[i].xz;vec3 n=oceanNormal(p);result[i]=vec4(oceanHeight(p),n);vec3 end=vec3(p.x,oceanMean(p).x-4.,p.y),eye=end+vec3(8,12,5);result[1024+i]=vec4(oceanInterfaceParameter(eye,end,oceanHeight(eye.xz),oceanHeight(end.xz),false),0,0,0);result[2048+i]=vec4(marineFogDepth(100.+float(i),max(0.,points[i].x*.02+10.),max(0.,points[i].z*.03+12.),800.,35.),0,0,0);}";
 auto stage=vsg::ShaderStage::create(VK_SHADER_STAGE_COMPUTE_BIT,"main",source);vsg::ShaderStages stages{stage};require(vsg::ShaderCompiler::create()->compile(stages),"production ocean field shader failed to compile");
