 auto params=vsg::vec4Array::create(voxelOceanUniformCount,vsg::vec4{});params->properties.dataVariance=vsg::DYNAMIC_DATA;auto points=vsg::vec4Array::create(count);std::mt19937 random(1234);std::uniform_real_distribution<float> range(-500,500);for(size_t i=0;i<count;++i){float span=i<256?.025f:1.f;(*points)[i]=vsg::vec4(range(random)*span,0,range(random)*span,0);}
