 auto datum=VoxelOcean::load({{"reference_surface",{{"grid_size",3},{"min_x",-500},{"min_z",-500},{"step_x",500},{"step_z",500},{"heights_m",{-1.5,-1.,-.5,-.5,0.,.5,.5,1.,1.5}}}}});
 auto set=vsg::DescriptorSet::create(layout,vsg::Descriptors{vsg::DescriptorBuffer::create(params,0,0,VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER),vsg::DescriptorBuffer::create(vsg::BufferInfoList{vsg::BufferInfo::create(buffer,0,3*count*sizeof(vsg::vec4))},1,0,VK_DESCRIPTOR_TYPE_STORAGE_BUFFER),vsg::DescriptorBuffer::create(points,2,0,VK_DESCRIPTOR_TYPE_STORAGE_BUFFER),vsg::DescriptorImage::create(vsg::Sampler::create(),makeOceanReferenceImage(*datum),4)});
 auto commands=vsg::Commands::create();commands->addChild(vsg::BindComputePipeline::create(vsg::ComputePipeline::create(pipeline,stage)));commands->addChild(vsg::BindDescriptorSet::create(VK_PIPELINE_BIND_POINT_COMPUTE,pipeline,0,set));commands->addChild(vsg::Dispatch::create(count/64,1,1));auto graph=vsg::CommandGraph::create(vsg::ref_ptr<vsg::Device>(context.device()),device.getPhysicalDevice()->getQueueFamily(VK_QUEUE_GRAPHICS_BIT));graph->addChild(commands);context.compile(graph);auto ocean=std::make_shared<VoxelOcean>(*datum);double heightError=0,normalError=0,interfaceError=0,fogError=0;
 for(bool withDatum:{false,true})for(double t:{0.,27.375,86400.125}){ocean->referenceSize=withDatum?3:0;ocean->wakes={{1.,2.,std::max(0.,t-1.1),.035,1.4,2.3,8.,1.2},{-3.,1.,std::max(0.,t-.4),.02,2.,2.,8.,.9}};ocean->refreshBounds();writeVoxelOceanField(*params,*ocean,t);params->dirty();context.execute(graph);void* mapped=nullptr;require(memory->map(0,3*count*sizeof(vsg::vec4),0,&mapped)==VK_SUCCESS,"ocean parity readback failed");std::vector<vsg::vec4> result(3*count);std::memcpy(result.data(),mapped,3*count*sizeof(vsg::vec4));memory->unmap();for(size_t i=0;i<count;++i){const auto& p=(*points)[i];const auto expected=ocean->sample(p.x,p.z,t);double integral=0;const double h0=std::max(0.,double(p.x)*.02+10.),h1=std::max(0.,double(p.z)*.03+12.);for(int j=0;j<1000;++j)integral+=std::exp(-(h0+(h1-h0)*(j+.5)/1000)/35.);const double fogReference=3.912*(100+i)/800.*integral/1000;fogError=std::max(fogError,std::abs(result[2*count+i].x-fogReference));heightError=std::max(heightError,std::abs(result[i].x-expected.height));const vsg::dvec3 end(p.x,ocean->meanSurface(p.x,p.z).x-4.,p.z),eye=end+vsg::dvec3(8,12,5);double distance;require(ocean->intersectSurface(eye,end-eye,t,vsg::length(end-eye),distance),"interface oracle ray missed");interfaceError=std::max(interfaceError,std::abs(result[count+i].x-distance/vsg::length(end-eye)));normalError=std::max(normalError,vsg::length(vsg::dvec3(result[i].y,result[i].z,result[i].w)-expected.normal));}}
 // Execute the production instanced foam raster pass and read its real
 // image. Persistence is reconstructed from saved deposits, not frame count.
 VoxelSceneSnapshot foamScene;auto foamWater=std::make_shared<VoxelOcean>(*VoxelOcean::load(nlohmann::json::object()));OceanFoam deposit;deposit.x=3;deposit.z=-4;deposit.length=12;deposit.width=3;deposit.strength=.8;deposit.seed=123;foamWater->foam.push_back(deposit);foamScene.ocean=foamWater;foamScene.fixedStep=.02;
 VoxelOceanDisplay display(foamScene,nullptr,context.device());rockyenv::AtmosphereState light;display.update(foamScene,vsg::dmat4{}, {0,10,0},light);
 auto foamGraph=vsg::CommandGraph::create(vsg::ref_ptr<vsg::Device>(context.device()),device.getPhysicalDevice()->getQueueFamily(VK_QUEUE_GRAPHICS_BIT));foamGraph->addChild(display.commands);context.compile(foamGraph);
 auto half=[](uint16_t bits){const int e=(bits>>10)&31,m=bits&1023;return (bits&32768?-1.:1.)*(e?std::ldexp(1.+m/1024.,e-15):std::ldexp(double(m),-24));};
 auto readFoam=[&]{context.execute(foamGraph);std::vector<uint16_t> pixels(512*512);context.readbackBatch({{display.foamImage()->imageView.get(),nullptr,VK_IMAGE_LAYOUT_GENERAL,pixels.size()*sizeof(uint16_t),pixels.data()}});double sum=0,x=0,z=0;for(int j=0;j<512;++j)for(int i=0;i<512;++i){const double v=half(pixels[j*512+i]);require(std::isfinite(v)&&v>=0,"GPU foam produced invalid radiance");sum+=v;x+=v*(-512+(i+.5)*2);z+=v*(-512+(j+.5)*2);}return vsg::dvec3(sum,x/std::max(sum,1e-12),z/std::max(sum,1e-12));};
 const auto fresh=readFoam();require(fresh.x>.1,"GPU foam did not rasterize saved deposit");foamScene.tick=400;display.update(foamScene,vsg::dmat4{}, {0,10,0},light);const auto aged=readFoam();require(aged.x>0&&aged.x<fresh.x*.8,"GPU foam failed persistent decay");
 const double az=vsg::radians(foamWater->windAzimuth);const vsg::dvec3 drift(foamWater->current.x+std::sin(az)*foamWater->windSpeed*.012,0,foamWater->current.z-std::cos(az)*foamWater->windSpeed*.012);
 require(std::abs((aged.y-fresh.y)-drift.x*8)<2.&&std::abs((aged.z-fresh.z)-drift.z*8)<2.,"GPU foam drift differs from shared current/wind");
 foamScene.tick=1500;display.update(foamScene,vsg::dmat4{}, {0,10,0},light);require(readFoam().x==0,"GPU expired foam left stale coverage");
