 std::cout<<"GPU ocean field maximum height error="<<heightError<<"m, normal error="<<normalError<<"; 6144 samples incl. geoid datum, active hull wakes and 24-hour phase rebase\n";std::cout<<"GPU safeguarded interface maximum range error="<<interfaceError*std::sqrt(233.)<<"m\n";std::cout<<"GPU marine fog maximum optical-depth error="<<fogError<<" versus independent numerical path integration\n";require(fogError<.001,"GPU marine fog integral differs from numerical extinction reference");require(interfaceError<.00005,"GPU display medium interface exceeds the millimetre error budget");require(heightError<.0001&&normalError<.0001,"GPU displayed wave differs from CPU buoyancy/optical field");return 0;
